		matched, err := doublestar.Match(lowered, normalizedOrigin)
		if err != nil {
			return false, fmt.Errorf("exclude_origins[%d]: invalid glob: %w", i, err)
		}
		if matched {
			return true, nil
		}
		if !strings.ContainsAny(pattern, "*?[{") && NormalizeOrigin(pattern) == normalizedOrigin {
			return true, nil
		}
	}
	return false, nil
}
