def hunks(path):
    s=open(path).read()
    out=[]; i=0
    while True:
        a=s.find('<<<<<<< ', i)
        if a<0: break
        m=s.find('\n=======\n', a); b=s.find('\n>>>>>>> ', m+1); e=s.find('\n', b+1)
