        out.append((a, e+1, ours, theirs)); i=e+1
    return s, out

def resolve(path, choices):
    # choices: list matching hunk count; each 'ours'|'theirs'|'both'|callable(ours,theirs)->text
    s, hs = hunks(path)
    if len(hs)!=len(choices): sys.exit(f"{path}: {len(hs)} hunks, {len(choices)} choices")
    outparts=[]; last=0
    for (a,e,ours,theirs),c in zip(hs,choices):
        outparts.append(s[last:a])
        if c=='ours': outparts.append(ours)
        elif c=='theirs': outparts.append(theirs)
